"use strict";(globalThis.webpackChunksummerz||=[]).push([[723605],{96625(e,n,t){t.r(n),t.d(n,{default:()=>c,metadata:()=>s});var s=t(174163),r=t(474848),i=t(28453);const o={slug:"2004/07/21-2",title:"\uc9c0\ub098\uace0 \ub098\ub2c8.",date:new Date("2004-07-21T22:00:00.000Z"),authors:"summerz",tags:["my view & mind"]},a={authorsImageUrls:[void 0]};function l(e){const n={p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.p,{children:(0,r.jsx)(n.strong,{children:"1"})}),"\n",(0,r.jsx)(n.p,{children:"\uc9d1\uc5d0\uc11c \uad11\uace0 \uc804\ub2e8\uc9c0\ub97c \ubcf4\uace0 \uc788\ub294\ub370, TV\uc5d0\uc11c Tom Hanks \uc8fc\uc5f0\uc758 Cast Away\ub97c \ud2c0\uc5b4\uc900\ub2e4. \ube44\ud589\uae30\uac00 \ucd94\ub77d\ud55c \ud6c4 \ub178\ub780 \uace0\ubb34\ubcf4\ud2b8(?) \ud0c0\uace0 \ud0c8\ucd9c\uc744 \uc2dc\ub3c4\ud558\ub294 (\ubb3c\ub860 \uc5b4\uc774\uc5c6\uc774 \uc2e4\ud328\ud558\uc9c0\ub9cc) \uc7a5\uba74, \uadf8\ub9ac\uace0 \uadf8\uc758 \uc808\uce5c\ud55c \uce5c\uad6c Wilson\uc744 \ub9cc\ub098\ub294 \uc7a5\uba74\uc774 \uc5bc\ud54f \uc9c0\ub098\uac04\ub2e4."}),"\n",(0,r.jsx)(n.p,{children:"About a Boy\uc5d0\uc11c Hugh Grant\uc758 \ub9d0\ucc98\ub7fc - \uc0ac\ub78c\ub4e4 \uc0ac\uc774\uc758 \uad00\uacc4\ub294 \uc12c\ucc98\ub7fc \uc774\ub8e8\uc5b4\uc838 \uc788\ub2e4\uace0 \ud558\ub294 \ub9d0\uc774 \uc0dd\uac01\ub09c\ub2e4. Cast Away\uc758 \uc8fc\uc778\uacf5\uc774 \uc774\uaca8\ub0b4\uace0 \uacac\ub38c\ub0b4\uc57c \ud588\ub358 \uc5ed\uacbd\uc5d0 \ube44\ud558\uba74 \uc544\ubb34 \uac83\ub3c4 \uc544\ub2c8\uc9c0\ub9cc - \uc5ec\uae30 \uc628\uc9c0 \uc5bc\ub9c8 \ub418\uc9c0 \uc54a\uc740 \ub0b4\uac00 \ub290\ub07c\uae30\uc5d0 \uc774 \uacf3\uc740, \uc608\uc804\uc5d0 \ub0b4\uac00 \uc9c0\ub0b4\ub358 \ud658\uacbd\uacfc \ube44\uad50\ud558\uc790\uba74 \uc12c\uacfc \uc12c \uc0ac\uc774\uc758 \uac70\ub9ac\uac00 \uc880 \uba3c \uacf3\uc778 \uac83 \uac19\ub2e4."}),"\n",(0,r.jsx)(n.p,{children:"\ubb3c\ub860 \uba87\uac00\uc9c0 \uc774\uc720\uac00 \uc788\ub2e4. \uc77c\ub2e8 \ub0b4 \uce5c\uad6c\ub4e4, \uc544\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc5ec\uae30\uc5d0 \uc5c6\uc73c\ub2c8 \ub9c8\uc74c\uc744 \ub098\ub20c \uc0ac\ub78c\uc774 \uc5c6\uae30 \ub54c\ubb38\uc774\uace0, \ud55c\uad6d \uc720\ud559\uc0dd\ub4e4\uc740 \uac01\uc790 \ud798\ub4e4\uac8c \uc0ac\ub290\ub77c \ub9c8\uc74c\uc758 \uc5ec\uc720\uac00 \uc5c6\ub294 \uac8c \ub2f9\uc5f0\ud560 \uc218\ub3c4 \uc788\uace0, \uc544\ub294 \uc0ac\ub78c \ubaa8\ub974\ub294 \uc0ac\ub78c\uc744 \ub5a0\ub098\uc11c \uc774 \uacf3\uc758 \ubb38\ud654\uac00 \ub0b4\uac00 \uc624\ub7ab\ub3d9\uc548 \uacaa\uc5c8\ub358 \ubb38\ud654\uc640 \uc0ac\ubb47 \ub2e4\ub974\uae30 \ub54c\ubb38\uc774\uae30\ub3c4 \ud558\uace0, \uae30\ubcf8\uc801\uc73c\ub85c \ub0b4 \uc774 \uacf3\uc5d0\uc11c\uc758 \uc5b8\uc5b4\uac00 \uc11c\ud234\uae30 \ub54c\ubb38\uc774\uae30\ub3c4 \ud558\ub2e4. \ubb3c\ub860 \uc2dc\uac04\uc774 \uc9c0\ub098\uba74 \ud558\ub098\uc529 \uadf8 \uc0c9\uae54\uc774 \uc605\uc5b4\uc9c0\ub294 \uac83\ub4e4\uc774 \ucc28\uce30\ucc28\uce30 \uc0dd\uae30\uaca0\uc9c0."}),"\n",(0,r.jsx)(n.p,{children:"\uc7ac\ubc0c\ub294 \uac74 - \uba70\uce60 \uc804\uc5d0 \ubb38\ub4dd \ub4e0 \uc0dd\uac01\uc774 \uc601\ud654 Cast Away\uc758 \uc8fc\uc778\uacf5\uc758 \ud589\ubcf4\uc640 \ube44\uc2b7\ud558\uac8c \uc0dd\uac01\ub41c\ub2e4\ub294 \uac83. \uc0c8\ub85c\uc6b4 \ud658\uacbd\uc5d0 \uc801\uc751\ud558\uace0, \uc0c8\ub85c\uc6b4 \uc0ac\ub78c\ub4e4\uc744 \uc54c\uac8c \ub418\uace0, \uc0c8\ub85c\uc6b4 \uc0dd\uac01\ub4e4\uc744 \ud558\uba70 - \uadf9\ubcf5\ud558\uac70\ub098 \uc778\uc815\ud558\uba74\uc11c, \ub9de\uc11c \uc2f8\uc6b0\uac70\ub098 \ud568\uaed8 \ud758\ub7ec\uac00\uba74\uc11c, \ub450\uace0 \uc628 \uac83\ub4e4\uc744 \uadf8\ub9ac\uc6cc \ud558\uac70\ub098 \uc0c8\ub85c \uc0dd\uaca8\ub09c \uac83\ub4e4\uc5d0 \uc560\ucc29\uc744 \ub290\ub07c\uba74\uc11c - \uc9c0\ub0b4\ub2e4\uac00 \uc2dc\uac04\uc774 \ud758\ub7ec \ub2e4\uc2dc \uc6d0\ub798\uc758 \uc790\ub9ac\ub85c \ub3cc\uc544\uac00\uac8c \ub418\uba74 \ub9ce\uc740 \uac83\ub4e4\uc774 \ub2ec\ub77c\uc838 \uc788\uc744 \uac83\uc774\ub77c\ub294 \uac83."}),"\n",(0,r.jsx)(n.p,{children:"\ub2e4\uc2dc \uc608\uc804 \uac19\uc744 \uc218\ub294 \uc5c6\ub2e4\ub294 \uac83. '\uc608\uc804 \uac19\uc744 \uc218 \uc5c6\ub2e4'\ub294 \ubb38\uc7a5\uc740 \uc660\uc9c0 '\uc608\uc804\uc774 \ub354 \uc88b\ub2e4'\ub294 \uc5b4\uac10\uc744 \uc8fc\ub294 \uac8c \uc0ac\uc2e4\uc774\uc9c0\ub9cc, \uadf8\ub7f0 \ub73b\uc774 \uc544\ub2c8\uace0\uc11c\ub77c\ub3c4 \uc5b4\uca0c\ub4e0 \uc608\uc804\uacfc\ub294 \ub2e4\ub974\ub2e4\ub294 \uac83\uc774\ub2e4. \uadf8\ub798, \uc5ec\ub7ec\uac00\uc9c0 \uc0ac\uc815\ub4e4\uc774 \ub354 \uc88b\uc544\uc9c8\uc9c0\ub3c4 \ubaa8\ub974\uc9c0. \uc18c\uc911\ud55c \uac83\ub4e4\uc744 \ub9ce\uc774 \uc54c\uac8c \ub420 \uc218\ub3c4 \uc788\uace0- \uadf8\ub798\uc11c \ub354\uc6b1 \ub178\ub825\ud558\uba70 \uc9c0\ub0bc \uc218\ub3c4 \uc788\uace0, \uc2dc\uac04\uc744 \uc9c0\ub0b4\uba70 \ub2ec\ub77c\uc9c4 \uc2a4\uc2a4\ub85c\uac00 \ub354\uc6b1 \uac15\ud574\uc838 \uc788\uc744 \uc218\ub3c4 \uc788\uace0..."}),"\n",(0,r.jsx)(n.p,{children:"\uadf8\ub7ec\ubbc0\ub85c, \uc2dc\uac04\uc774 \ud758\ub7ec \ub2e4\uc2dc \ub3cc\uc544\uc654\uc744 \ub54c \uc18c\uc911\ud55c \uac83\ub4e4 \uc911 - \uc608\uc804\uacfc \uac19\uc740 \uac83 \ud639\uc740 \uc608\uc804\ubcf4\ub2e4 \ub354 \ub098\uc544\uc9c4 \uac83\ub4e4\uc774 \uc788\ub2e4\ub294 \uac83. \uadf8\uac74, \uadf8\ub807\uac8c \uc18c\uc911\ud55c \uc0ac\ub78c\ub4e4\uc740 \uc18c\uc911\ud55c \uac83\ub4e4\uc740 \uc190\uac00\ub77d \uc0ac\uc774\ub97c \ube60\uc838\ub098\uac00\ub2e4\uac00 \ubc18\uc9dd\uac70\ub9ac\uba70 \uc190 \ub05d\uc5d0 \ub0a8\ub294 \uba87 \uc54c\uc758 \ubaa8\ub798\uc54c\ucc98\ub7fc - \uadf8\ub807\uac8c \ub0a8\uac8c \ub41c\ub2e4\ub294 \ub73b\uc774\ub77c\uace0 \uc0dd\uac01\ud55c\ub2e4."}),"\n",(0,r.jsx)(n.p,{children:(0,r.jsx)(n.strong,{children:"2"})}),"\n",(0,r.jsx)(n.p,{children:"\uc790\uae30 \uc804\uc5d0 \uc7a0\uae50 \ubc16\uc5d0 \ub098\uac00\uc11c \ud558\ub298\uc744 \ubcf4\ub2e4\uac00 \ubb38\ub4dd \ud55c\uad6d\uc5d0 \ub450\uace0 \uc628 \ubc15\uc2a4\uac00 \uc0dd\uac01\ub0ac\ub2e4. '\uc544, \uac70\uae30\uc5d0 \uc601\uc5b4\ucc45\ub4e4 \uc788\ub294\ub370... \uac70\uae30 \uc77d\uc744 \ub9cc\ud55c \ucc45\ub4e4\uc774 \uc880 \uc788\uc744\ud150\ub370...' \ud558\ub294 \uc0dd\uac01. '\uc0b4\ub2e4\ubcf4\uba74 \uc5b8\uc820\uac04, \uc5b4\ub518\uac00\uc5d0 \uc4f8\ubaa8\uac00 \uc788\uaca0\uc9c0' \ud558\uba70 \uc804\ud600 \uad6c\uccb4\uc801\uc774\uc9c0 \uc54a\uc740 \ubc1c\uc0c1\uc73c\ub85c \ubb34\uc5b8\uac00\ub97c \ub0a8\uaca8\ub454 \uac83\ub4e4\uc740 \ub300\ubd80\ubd84 \uc4f0\ub808\uae30\uac00 \ub41c\ub2e4."}),"\n",(0,r.jsx)(n.p,{children:"\ud63c\uc790 \uc0b0\uc9c0 10\uc5ec\ub144\uc774 \uc9c0\ub098\uba74\uc11c \uc774\uc81c\uc11c\uc57c \uac04\uc2e0\ud788 \ub290\ub07c\ub294 \uac74 (\uc544\uc9c1\ub3c4 \uc2e4\ucc9c\uc73c\ub85c \uc798 \uc62e\uae30\uc9c4 \ubabb\ud558\uc9c0\ub9cc), '\uc774 \uacf3\uc774 \ub0b4 \uc9d1\uc774\uc57c, \ub0b4 \uace0\ud5a5\uc774\uc57c.' \ub77c\uace0 \uc0dd\uac01\ub418\ub294 \uacf3\uc774 \uc544\ub2c8\ub77c\uba74 \ubb34\uc5b8\uac00\ub97c \uc313\uc544\ub458 \uc774\uc720\uac00 \uc804\ud600 \uc5c6\ub2e4\ub294 \uac70\ub2e4."}),"\n",(0,r.jsx)(n.p,{children:"\ubb3c\ub860 \uc5b8\uc820\uac00 \uc4f8\ubaa8\uac00 \uc788\ub294 \uac83\ub4e4\ub3c4 \uc788\ub2e4. \ub9e4\ubc88 \uc9d1\uc744 \uc62e\uae38 \ub54c\ub9c8\ub2e4 \uba40\ud2f0\ud0ed\uc744 \uc0ac\ub294 \uac74 \ubc14\ubcf4 \uac19\uc740 \uc9d3\uc774\uace0, \ub9e4\ubc88 \uc0c8\ub85c \ubc25\uacf5\uae30\ub97c \uc0ac\ub294 \uac83\ub3c4 \ubc14\ubcf4 \uac19\uc740 \uc9d3\uc774\uace0, \ub9e4\ubc88 \uc637\uc7a5\uc744 \uc0c8\ub85c \uc0ac\ub294 \uac83\ub3c4 \ubc14\ubcf4 \uac19\uc740 \uc9d3\uc774\ub2e4. (\uc0c8\ub85c\uc6b4 \ud544\uc694 \ub54c\ubb38\uc5d0 \uc0ac\ub294 \uac74 \ubab0\ub77c\ub3c4.) \uadf8\ub807\uc9c0\ub9cc, \uadf8\ub807\uc9c0 \uc54a\uc740 \uac83\ub4e4\uc740? \uc880 \uc544\uae5d\uac8c \uc0dd\uac01\ub418\ub3c4 \ub2e4 \ubc84\ub824\ub3c4 \ub41c\ub2e4. \ubb3c\ub860 \uc4f0\ub808\uae30\ud1b5\uc5d0\ub2e4 \uccd0\ubc15\uc73c\ub77c\ub294 \uc18c\ub9ac\uac00 \uc544\ub2c8\ub77c \ud544\uc694\ud55c \uc0ac\ub78c\uc5d0\uac8c \uc918\ub3c4 \ub418\uace0, \uc544\ub294 \uc0ac\ub78c\ub4e4\ub07c\ub9ac \ub098\ub204\uba74 \ub418\ub294 \uac83\uc774\ub2e4."}),"\n",(0,r.jsx)(n.p,{children:"\ud639 \uba40\ub9ac \uac14\ub2e4\uac00 \ub2e4\uc2dc \uc81c\uc790\ub9ac\ub85c \ub3cc\uc544\uc654\uc744 \ub54c, \uc544\ub2c8\uba74 \uc0c8\ub85c\uc6b4 \uacf3\uc5d0 \uac14\uc744 \ub54c (\uadf8\ub7f0 \ub9e4\uc6b0 \uc77c\uc0c1\uc801\uc774\uace0, \uc790\uc8fc \uc0ac\uc6a9\ub418\ub294 \uac83\ub4e4\uc744 \uc81c\uc678\ud558\uace0) \uadf8\uac8c \uc5c6\uc5b4\uc11c - \ubd88\ud3b8\ud574\uc11c \uc8fd\uc744 \uac83 \uac19\uac70\ub098, \uadf8\uac70 \uc5c6\uc774 \ubabb \uc0b0\ub2e4\uac70\ub098 \ud558\ub294 \uac83\ub4e4\uc774 \uc5bc\ub9c8\ub098 \ub420 \uac83\uc778\uac00. \uadf8\ub807\uac8c \uc911\uc694\ud55c \uac83\uc774\uc5c8\ub2e4\uba74 \uc9c0\ub2c8\uace0 \uc788\uc5c8\uc5b4\uc57c \ub2f9\uc5f0\ud55c \uac70\uc9c0, \ub5a0\ub098\uc9c0 \ub9d0\uc558\uc5b4\uc57c \ud558\ub294 \uac70\uc9c0 - \uc544\ub2c8, \uc801\uc5b4\ub3c4 \uc774\uac74 \uaf2d \ubcf4\uad00\ud574\uc57c \ud55c\ub2e4\uace0 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uc54c\ub9ac\uac70\ub098 \uba54\ubaa8\ub97c \ud574\ub450\uac70\ub098 \ud588\uc5b4\uc57c\uc9c0."}),"\n",(0,r.jsx)(n.p,{children:"\uc0b4\uba74\uc11c \uc18c\uc911\ud558\ub2e4\uace0 \uc5ec\uaca8\uc9c0\ub294 \uc0ac\ub78c\ub4e4\uc774 \ubb3c\uac74\ub4e4\uc774 \uac00\uce58\ub4e4\uc774 \ud558\ub098\uc529 \ub298\uc5b4\ub0a0 \ub54c\ub9c8\ub2e4 \ub450\ub835\ub2e4. \uadf8\uac78 \uac10\ub2f9\ud574\uc57c \ud558\ub294 \ub0b4 \uc790\uc2e0\uc774 \ub450\ub835\uace0, \uadf8\uac83\ub4e4\uc758 \uac00\uce58\ub4e4\uc774 \uc11c\ub85c \ucda9\ub3cc\ud560 \ub54c\ub9c8\ub2e4 \ub450\ub835\uace0, \uc18c\uc911\ud55c \uac83\ub4e4\uc774 \ub298\uc5b4\ub0a0\uc218\ub85d \ub0b4\uac00 \uc54c\uace0 \uc788\ub358 \uc18c\uc911\ud568\uc758 \uc758\ubbf8\uac00 \uc810\uc810 \ud76c\ubbf8\ud574\uc9c0\ub294 \uac83 \uac19\uc544 \ub450\ub835\ub2e4. \ub0b4\uac00 \uc0ac\ub77c\uc9c0\ub294 \uac83\ub3c4 \ub450\ub835\uc9c0\ub9cc, \ub0b4\uac00 \ubb34\uc758\ubbf8\ud55c \uac83\ub4e4\uc744 \ub0a8\uae30\uace0 \uc788\ub294 \uac83 \uac19\uc544 \ub450\ub835\uae30\ub3c4 \ud558\ub2e4."}),"\n",(0,r.jsx)(n.p,{children:"\uc785\uc73c\ub85c\ub294 \uc790\uc720\ub86d\uace0 \uc2f6\ub2e4\uace0 \uc774\uc57c\uae30\ud558\uba74\uc11c, \ub9e4\uc77c \uc218\ub9ce\uc740 \uac83\ub4e4\uc5d0 \ubb36\uc5ec \uc788\ub294 \ub098\ub97c \ubcf8\ub2e4. \ub098\ub294 \uc815\ub9d0 \uc790\uc720\ub86d\uace0 \uc2f6\uc740\uac00."}),"\n",(0,r.jsx)(n.p,{children:"11 July 2004, Clemton Park NSW Australia\uc5d0\uc11c."})]})}function c(e={}){const{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(l,{...e})}):l(e)}t.d(n,["assets",0,a,"contentTitle",0,void 0,"frontMatter",0,o,"toc",0,[]])},28453(e,n,t){t.d(n,{R:()=>o,x:()=>a});var s=t(296540);const r={},i=s.createContext(r);function o(e){const n=s.useContext(i);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function a(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:o(e.components),s.createElement(i.Provider,{value:n},e.children)}},174163(e){e.exports=JSON.parse('{"permalink":"/blog/2004/07/21-2","source":"@site/blog/2004/07/2004-07-21-2/index.md","title":"\uc9c0\ub098\uace0 \ub098\ub2c8.","description":"1","date":"2004-07-21T22:00:00.000Z","tags":[{"inline":true,"label":"my view & mind","permalink":"/blog/tags/my-view-mind"}],"readingTime":2.83,"hasTruncateMarker":true,"authors":[{"name":"summerz","imageURL":"https://github.com/summerz.png","key":"summerz","page":null}],"frontMatter":{"slug":"2004/07/21-2","title":"\uc9c0\ub098\uace0 \ub098\ub2c8.","date":"2004-07-21T22:00:00.000Z","authors":"summerz","tags":["my view & mind"]},"unlisted":false,"prevItem":{"title":"step by step","permalink":"/blog/2004/07/21"},"nextItem":{"title":"\'\uadf8\uac83\'\uc744 \uc54c\uc544\ub0b4\ub2e4","permalink":"/blog/2004/07/20"}}')}}]);